package com.nightbeam.donutshards.shop;
import com.nightbeam.donutshards.gui.ShopHolder;import com.nightbeam.donutshards.model.*;import com.nightbeam.donutshards.scheduler.SchedulerService;import com.nightbeam.donutshards.service.MessageService;import com.nightbeam.donutshards.transaction.TransactionService;import net.kyori.adventure.text.Component;import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.inventory.*;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.persistence.PersistentDataType;import org.bukkit.plugin.Plugin;import java.util.*;import java.util.concurrent.ConcurrentHashMap;
public final class ShopService implements Listener {private final Plugin plugin;private final TransactionService tx;private final SchedulerService scheduler;private final MessageService messages;private final Set<UUID> processing=ConcurrentHashMap.newKeySet();private final NamespacedKey tokenKey;public ShopService(Plugin plugin,TransactionService tx,SchedulerService scheduler,MessageService messages){this.plugin=plugin;this.tx=tx;this.scheduler=scheduler;this.messages=messages;tokenKey=new NamespacedKey(plugin,"purchase-token");}
 public void open(Player p){var holder=new ShopHolder(UUID.randomUUID());var inv=Bukkit.createInventory(holder,27,Component.text("Cosmic Confection Exchange"));holder.inventory(inv);var item=new ItemStack(Material.COOKIE);var meta=item.getItemMeta();meta.displayName(messages.render("<gradient:#ffd166:#ff78b8>Starlight Cookie</gradient>",Map.of()));meta.lore(List.of(Component.text("Price: 25 shards")));item.setItemMeta(meta);inv.setItem(13,item);p.openInventory(inv);}
 @EventHandler public void click(InventoryClickEvent e){if(!(e.getView().getTopInventory().getHolder() instanceof ShopHolder)||!(e.getWhoClicked() instanceof Player p))return;e.setCancelled(true);if(e.getRawSlot()!=13||!processing.add(p.getUniqueId()))return;purchase(p);}
 @EventHandler public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof ShopHolder)e.setCancelled(true);}
 private void purchase(Player p){var id=UUID.randomUUID();var ctx=new MutationContext(TransactionType.SHOP_PURCHASE,"shop:starlight-cookie",p.getUniqueId(),"purchase:"+id,Map.of("item","starlight-cookie"));tx.remove(p.getUniqueId(),25,ctx).whenComplete((result,error)->scheduler.entity(p,()->{try{if(error!=null||!result.success()){messages.send(p,"<red>Purchase failed: <reason></red>",Map.of("reason",error==null?result.reason():"storage_error"));return;}var item=new ItemStack(Material.COOKIE);var meta=item.getItemMeta();meta.displayName(messages.render("<gradient:#ffd166:#ff78b8>Starlight Cookie</gradient>",Map.of()));meta.getPersistentDataContainer().set(tokenKey,PersistentDataType.STRING,id.toString());item.setItemMeta(meta);var leftovers=p.getInventory().addItem(item);if(!leftovers.isEmpty())leftovers.values().forEach(x->p.getWorld().dropItemNaturally(p.getLocation(),x));messages.send(p,"<green>Purchase complete. Balance: <balance></green>",Map.of("balance",Long.toString(result.transaction().newBalance())));}finally{processing.remove(p.getUniqueId());}},()->processing.remove(p.getUniqueId())));}
 public void clear(){processing.clear();}}
